def count_maximal_cocktails(nodes_list, edges_list, difficulty):
    from itertools import combinations
    from collections import defaultdict

    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    nodes = set(nodes_list)

    for u, v in edges_list:
        graph[u].append(v)
        graph[v].append(u)

    def is_valid_cocktail(cocktail):
        for u in cocktail:
            for v in cocktail:
                if u != v and (u, v) in edges_list or (v, u) in edges_list:
                    return False
        return True

    def find_maximal_cocktails(cocktail):
        cocktails = []
        for r in range(len(cocktail), len(cocktail)-1, -1):
            for combo in combinations(cocktail, r):
                if is_valid_cocktail(combo):
                    cocktails.append(list(combo))
                    break
        return cocktails

    if difficulty == 'easy':
        independent_set_sizes = len(cocktails) for size in range(1, len(nodes) + 1) for nodes in combinations(nodes, size):
            if is_valid_cocktail(nodes):
                yield from find_maximal_cocktails(nodes)

        return sum(1 for _ in independent_set_sizes)

    elif difficulty == 'normal':
        independent_set_sizes = len(cocktails) for size in range(1, len(nodes) + 1) for nodes in combinations(nodes, size):
            if is_valid_cocktail(nodes):
                yield from find_maximal_cocktails(nodes)
        return independent_set_sizes

