class PeerCountMaximalCocktailsCustomStrategy:

    def find_independent_sets(self, nodes: List[int], edges: List[tuple]) -> List[List[int]]:
        """Finds all possible independent sets (disjoint sets) in the given graph."""
        all_sets = [[]]
        for i in range(1, len(nodes) + 1):
            subsets = combinations(nodes, i)
            independent_sets = []
            for subset in subsets:
                conflicts = any((node in subset and (component, node) in edges or (node, component) in edges) for component in subset)
                if not conflicts:
                    independent_sets.append(list(subset))
            all_sets.extend(independent_sets)
        return all_sets

    def find_maximal_sets(self, independent_sets: List[List[int]]) -> List[List[int]]:
        """Finds maximal independent sets (cocktails) from all independent sets."""
        max_sets = []
        for set_ in independent_sets:
            if not any(set_.issubset(other_set) or other_set.issubset(set_) for other_set in max_sets):
                max_sets.append(list(set_))
        return max_sets

    def CountMaximalCocktails(self, nodes: List[int], edges: List[tuple], difficulty: str) -> List[Any]:
        independent_sets = self.find_independent_sets(nodes, edges)
        if difficulty == 'easy':
            # Return the number of maximal cocktails
            maximal_sets = self.find_maximal_sets(independent_sets)
            return len(maximal_sets)
        elif difficulty == 'normal':
            # Return the list of maximal cocktails explicitly
            return maximal_sets

