def find_maximal_cocktails(nodes_list, edges_list, difficulty='easy'):
    import itertools
    from collections import defaultdict

    if difficulty == 'easy':
        return count_maximal_cocktails(nodes_list, edges_list)
    elif difficulty == 'normal':
        return list_maximal_cocktails(nodes_list, edges_list)

    def count_maximal_cocktails(nodes, edges):
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        all_cocktails = []

        def backtrack(starting_node, visited):
            stack = [starting_node]
            temp = []
            while stack:
                node = stack.pop()
                if node not in visited:
                    temp.append(node)
                    visited.add(node)
                    stack.extend(graph[node])
            return temp

        visited = set()
        for node in nodes:
            if node not in visited:
                temp = backtrack(node, visited)
                if temp:
                    all_cocktails.append(tuple(sorted(temp)) if len(temp) > 1 else (temp[0],))

        maximal_cocktails = set(all_cocktails)
        return len(maximal_cocktails)

    def list_maximal_cocktails(nodes, edges):
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        maximal_cocktails = []
        size = len(nodes)

        def dfs(visited, current_cocktail):
            visited.add(current_cocktail)
            for node in graph[current_cocktail[0]]:
                next_cocktail = current_cocktail + (node,) if len(current_cocktail) == 1 else [current_cocktail[0], node]
                dfs(visited, next_cocktail)
            if len(current_cocktail) == size:
                maximal_cocktails.append(tuple(sorted(current_cocktail)) if len(current_cocktail) > 1 else (current_cocktail,))

        for node in nodes:
            dfs(set(), (node,))

        return [list(cocktail) for cocktail in set(maximal_cocktails)]

